const question = $('1. Capture question').first().json.question;
const found=$input.all().map(i=>i.json).filter(i=>i.document || i.pageContent);
if(!found.length) throw new Error('Knowledge is empty. Close chat, click Execute workflow to LOAD KNOWLEDGE, then open chat again. Use the same workflow and embedding model.');
const docs=found.map((r,i)=>{const d=r.document||r; let text=d.pageContent||'';try{const p=JSON.parse(text);if(p.text)text=p.text;}catch{} const match=text.match(/\[SOURCE ([^\]]+)\]/);return {source:match?match[1]:(d.metadata?.source||'Kaapi knowledge'),text,score:r.score};});
return [{json:{question,context:docs.map((d,i)=>`CHUNK ${i+1}\n${d.text}`).join('\n\n'),sources:docs.map(d=>d.source),retrieved_chunks:docs}}];
